<?php defined('BASEPATH') OR exit('No direct script access allowed');class Helpdesk_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function tickets($o,$f=array()){$this->db->where('organization_id',$o);foreach(array('status','priority')as$k)if(!empty($f[$k]))$this->db->where($k,$f[$k]);if(array_key_exists('assigneeId',$f))$f['assigneeId']===''?$this->db->where('assignee_id IS NULL',NULL,FALSE):$this->db->where('assignee_id',$f['assigneeId']);if(!empty($f['q']))$this->db->group_start()->like('subject',$f['q'])->or_like('number',$f['q'])->or_like('requester_name',$f['q'])->or_like('description',$f['q'])->group_end();return array_map(array($this,'view'),$this->db->order_by('created_at','DESC')->get('helpdesk_tickets')->result_array());}function ticket($o,$id,$raw=FALSE){$r=$this->db->where(array('organization_id'=>$o,'id'=>$id))->get('helpdesk_tickets')->row_array();return$r?($raw?$r:$this->view($r)):NULL;}function detail($o,$id){$t=$this->ticket($o,$id);if(!$t)return NULL;$t['comments']=$this->comments($o,$id);return$t;}function create($o,$u,$d){$now=date('Y-m-d H:i:s');$p=$d['priority']??'medium';$this->db->trans_start();$this->db->query('INSERT INTO helpdesk_sequences(organization_id,next_number) VALUES(?,1001) ON DUPLICATE KEY UPDATE next_number=LAST_INSERT_ID(next_number+1)',array($o));$n=$this->db->insert_id()?:1001;$id=$this->uuid();$status=$d['status']??'new';$r=array('id'=>$id,'organization_id'=>$o,'number'=>'HD-'.$n,'subject'=>trim($d['subject']),'description'=>$d['description']??NULL,'status'=>$status,'priority'=>$p,'channel'=>$d['channel']??'web','requester_name'=>trim($d['requesterName']),'requester_email'=>$d['requesterEmail']??NULL,'assignee_id'=>$d['assigneeId']??NULL,'contact_id'=>$d['contactId']??NULL,'company_id'=>$d['companyId']??NULL,'tags'=>json_encode($d['tags']??array()),'sla_due_at'=>date('Y-m-d H:i:s',strtotime('+'.$this->sla($p).' hours')),'resolved_at'=>$status==='resolved'?$now:NULL,'closed_at'=>$status==='closed'?$now:NULL,'created_at'=>$now,'updated_at'=>$now);$this->db->insert('helpdesk_tickets',$r);$this->crm($o,$u,$r);$this->db->trans_complete();return$this->ticket($o,$id);}function update_ticket($o,$id,$u,$d){$r=$this->ticket($o,$id,TRUE);if(!$r)return NULL;$map=array('subject'=>'subject','description'=>'description','priority'=>'priority','channel'=>'channel','requesterName'=>'requester_name','requesterEmail'=>'requester_email','assigneeId'=>'assignee_id','contactId'=>'contact_id','companyId'=>'company_id');$s=array();foreach($map as$i=>$k)if(array_key_exists($i,$d))$s[$k]=$d[$i];if(isset($d['tags']))$s['tags']=json_encode($d['tags']);if(isset($d['priority']))$s['sla_due_at']=date('Y-m-d H:i:s',strtotime('+'.$this->sla($d['priority']).' hours'));$s['updated_at']=date('Y-m-d H:i:s');$this->db->where(array('organization_id'=>$o,'id'=>$id))->update('helpdesk_tickets',$s);$this->crm($o,$u,array_merge($r,$s));return$this->ticket($o,$id);}function assign($o,$id,$a){if(!$this->ticket($o,$id))return NULL;$this->db->where(array('organization_id'=>$o,'id'=>$id))->update('helpdesk_tickets',array('assignee_id'=>$a,'updated_at'=>date('Y-m-d H:i:s')));return$this->ticket($o,$id);}function transition($o,$id,$to){$r=$this->ticket($o,$id,TRUE);if(!$r)return array(NULL,NULL);if($r['status']===$to)return array($this->view($r),NULL);$a=array('new'=>array('open','pending','resolved','closed'),'open'=>array('pending','resolved','closed'),'pending'=>array('open','resolved','closed'),'resolved'=>array('closed'),'closed'=>array());if(!in_array($to,$a[$r['status']],TRUE))return array(NULL,'INVALID_TRANSITION');$now=date('Y-m-d H:i:s');$s=array('status'=>$to,'updated_at'=>$now,'resolved_at'=>$to==='resolved'?$now:($to==='closed'?($r['resolved_at']?:$now):NULL),'closed_at'=>$to==='closed'?$now:NULL);$this->db->where(array('organization_id'=>$o,'id'=>$id))->update('helpdesk_tickets',$s);return array($this->ticket($o,$id),NULL);}function remove_ticket($o,$id){$this->db->where(ar